use crate::aap::caps::types::{AgentResponse, Intent, LlmError};
use crate::aap::caps::{kb_read, tool_llm};

struct Node;

const MAX_QUESTION: usize = 512;
const MAX_ROUNDS: usize = 4;
const MAX_HITS: usize = 20;
const MAX_HIT_CHARS: usize = 512;

const SYSTEM: &str = "You are a customer support assistant. Answer using only the \
provided knowledge. If you need more information, request the 'lookup' tool with a \
short query.";

fn clip(s: &str, n: usize) -> String {
    s.chars().take(n).collect()
}

fn error(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > MAX_QUESTION {
            return error("question exceeds maximum length");
        }

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        prompt.push('\n');

        if !ctx.knowledge.is_empty() {
            prompt.push_str("Knowledge:\n");
            for item in ctx.knowledge.iter().take(MAX_HITS) {
                prompt.push_str("- ");
                prompt.push_str(&clip(item, MAX_HIT_CHARS));
                prompt.push('\n');
            }
        }

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    // The node's scope is exactly [lookup]; refuse anything else.
                    if req.tool != "lookup" {
                        return error("model requested a tool outside this node's scope");
                    }

                    let query = clip(&req.query, MAX_QUESTION);
                    let hits = kb_read::lookup(&query);

                    prompt.push_str("\nLookup for \"");
                    prompt.push_str(&query);
                    prompt.push_str("\" returned:\n");
                    if hits.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for hit in hits.iter().take(MAX_HITS) {
                            prompt.push_str("- ");
                            prompt.push_str(&clip(hit, MAX_HIT_CHARS));
                            prompt.push('\n');
                        }
                    }
                }
            }
        }

        error("model did not produce an answer within the tool-round limit")
    }
}

export!(Node);
```

